213	
214	    /**
215	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
216	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
217	     * Validation already rejects {@code null} values and the pattern-constrained fields
218	     * when blank, but {@code address} and {@code city} have no pattern, so a
219	     * whitespace-only value would otherwise slip through.
220	     *
221	     * @param ownerFieldsDto the submitted owner fields
222	     * @throws RequiredFieldsMissingException if any required field is missing or blank
223	     */
224	    /**
225	     * Common street-type abbreviations expanded during address normalization. Keys are the
226	     * upper-cased abbreviation tokens; values are their canonical expansions.
227	     */
228	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
229	        "ST", "STREET",
230	        "RD", "ROAD",
231	        "AVE", "AVENUE");
232	
233	    /**
234	     * Normalizes the submitted address on create and writes the canonical value back onto the
235	     * request so it is persisted, echoed back, and used for every downstream address comparison
236	     * (household duplicate detection and the household id). The value is trimmed, internal
237	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
238	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
239	     * {@code null} address is left untouched so the required-field check can report it as missing.
240	     *
241	     * @param ownerFieldsDto the submitted owner fields
242	     */
243	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
244	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
245	    }
246	
247	    /**
248	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
249	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
250	     * expanded to its full form. A {@code null} value is returned unchanged.
251	     *
252	     * @param raw the address to canonicalize, possibly {@code null}
253	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
254	     */
255	    private static String normalizeAddress(String raw) {
256	        if (raw == null) {
257	            return null;
258	        }
259	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
260	        if (collapsed.isEmpty()) {
261	            return collapsed;
262	        }
263	        String[] tokens = collapsed.split(" ");
264	        StringBuilder sb = new StringBuilder(collapsed.length());
265	        for (int i = 0; i < tokens.length; i++) {
266	            if (i > 0) {
267	                sb.append(' ');
268	            }
269	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
270	        }
271	        return sb.toString();
272	    }
273	
274	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
275	        List<String> errors = new ArrayList<>();
276	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
277	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
278	        requireText("address", ownerFieldsDto.getAddress(), errors);
279	        requireText("city", ownerFieldsDto.getCity(), errors);
280	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
281	        if (!errors.isEmpty()) {
282	            throw new RequiredFieldsMissingException(errors);
283	        }
284	    }
285	
286	    private static void requireText(String field, String value, List<String> errors) {
287	        if (value == null || value.isBlank()) {
288	            errors.add(field);
289	        }
290	    }
291	
292	    /**
293	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
294	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
295	     * and echoed back in that form.
296	     *
297	     * @param ownerFieldsDto the submitted owner fields
298	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
299	     *                                        valid E.164 number
300	     */
301	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
302	        String e164 = toE164(ownerFieldsDto.getTelephone());
303	        if (e164 == null) {
304	            throw new RequiredFieldsMissingException(List.of("telephone"));
305	        }
306	        ownerFieldsDto.setTelephone(e164);
307	    }
308	
309	    /**
310	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
311	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
312	     * and country code are present they are kept; otherwise country code {@code '+61'} is
313	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
314	     * must contain 8 to 15 digits after the {@code '+'}.
315	     *
316	     * @param raw the submitted telephone, possibly {@code null}
317	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
318	     */
319	    private static String toE164(String raw) {
320	        if (raw == null) {
321	            return null;
322	        }
323	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
324	        String digits;
325	        if (cleaned.startsWith("+")) {
326	            digits = cleaned.substring(1);
327	        } else {
328	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
329	            digits = "61" + national;
330	        }
331	        if (!digits.matches("[0-9]{8,15}")) {
332	            return null;
333	        }
334	        return "+" + digits;
335	    }
336	
337	    /**
338	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
339	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
340	     * each stored owner's telephone is normalized the same way before comparison so differing
341	     * input formats collapse to the same value.
342	     *
343	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
344	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
345	     *                                     same E.164 telephone
346	     */
347	    /**
348	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
349	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
350	     * the parts may contain whitespace or a second {@code @}.
351	     */
352	    private static final Pattern EMAIL_PATTERN =
353	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
354	
355	    /**
356	     * Normalizes the submitted email when present: the value is trimmed, required to be a
357	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
358	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
359	     *
360	     * @param ownerFieldsDto the submitted owner fields
361	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
362	     */
363	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
364	        String email = ownerFieldsDto.getEmail();
365	        if (email == null) {
366	            return;
367	        }
368	        String trimmed = email.strip();
369	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
370	            throw new InvalidEmailException(email);
371	        }
372	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
373	    }
374	
375	    /**
376	     * Defaults the registration date on create: when the client does not supply a
377	     * {@code registrationDate}, it is set to the server's current date so it is persisted
378	     * and echoed back in ISO 'YYYY-MM-DD' format. A supplied value is left untouched.
379	     *
380	     * @param ownerFieldsDto the submitted owner fields
381	     */
382	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
383	        if (ownerFieldsDto.getRegistrationDate() == null) {
384	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
385	        }
386	    }
387	
388	    /**
389	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'}
390	     * where LAST3 is the upper-cased first three letters of {@code lastName} and NNNN is a
391	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
392	     * (e.g. {@code 'SMI-0007'}).
393	     *
394	     * @param owner the owner being created (with its {@code lastName} already set)
395	     */
396	    private void assignCustomerCode(Owner owner) {
397	        String lastName = owner.getLastName();
398	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
399	        int sequence = this.clinicService.findAllOwners().size() + 1;
400	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
401	    }
402	
403	    /**
404	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
405	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
406	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
407	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
408	     * canonicalized fields, every owner in the same household — including one joining an existing
409	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
410	     * order.
411	     *
412	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
413	     */
414	    private void assignHouseholdId(Owner owner) {
415	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
416	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
417	    }
418	
419	    /**
420	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
421	     *
422	     * @param value the string to hash
423	     * @return the 64-character lower-case hex digest
424	     */
425	    private static String sha256Hex(String value) {
426	        try {
427	            byte[] digest = MessageDigest.getInstance("SHA-256")
428	                .digest(value.getBytes(StandardCharsets.UTF_8));
429	            StringBuilder sb = new StringBuilder(digest.length * 2);
430	            for (byte b : digest) {
431	                sb.append(String.format("%02x", b));
432	            }
433	            return sb.toString();
434	        }
435	        catch (NoSuchAlgorithmException e) {
436	            throw new IllegalStateException("SHA-256 not available", e);
437	        }
438	    }
439	
440	    private void rejectDuplicateTelephone(String normalizedTelephone) {
441	        boolean duplicate = this.clinicService.findAllOwners().stream()
442	            .map(Owner::getTelephone)
443	            .map(OwnerRestControllerV1::toE164)
444	            .filter(telephone -> telephone != null)
445	            .anyMatch(normalizedTelephone::equals);
446	        if (duplicate) {
447	            throw new DuplicateTelephoneException(normalizedTelephone);
448	        }
449	    }
450	
451	    /**
452	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
453	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
454	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
455	     * still counts as the same household. The check is skipped when the request opts in via
456	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
457	     * the existing one.
458	     *
459	     * @param ownerFieldsDto the submitted owner fields
460	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
